/*
 * PORTED, NEVER RE-DERIVED: Head and headline -> src/lib/components/staff/LearnerShell.tsx
 * (TASK-L165 §2). Three facts about the LEARNER, read off the programme in the
 * MODEL's order — which is why this takes `inOrder` from Logic/Ordered timeline
 * rather than sorting anything itself.
 */
function plain(x) {
  if (x === null || x === undefined) return x;
  if (Array.isArray(x)) return x.map(plain);
  if (typeof x === 'object') {
    if (typeof x.get === 'function' && x.data && typeof x.data === 'object') return plain(x.data);
    if (Array.isArray(x.items)) return plain(x.items);
    const out = {};
    for (const k of Object.keys(x)) out[k] = plain(x[k]);
    return out;
  }
  return x;
}
const fill = (t, v) => String(t || '').replace(/\{(\w+)\}/g, (m, k) => (k in v ? String(v[k]) : m));

/* Wait for the words and the person; throw only on words that arrived WITHOUT
   this page's namespace, which is a wiring fault rather than an arrival order
   (Logic/Roster filter's two halves, L164). */
const copy = plain(Inputs.copy);
const person = plain(Inputs.person);
if (!copy || !person) return;
const W = (copy.people || {}).learner;
if (!W) throw new Error('People/Head: the copy has no people.learner namespace — wire it from a coach-audience Data/Strings');
const TL = copy.timeline || {};
const entries = plain(Inputs.entries) || [];

/* One owner for every date on this page, pinned to UTC (Logic/Ordered timeline's
   rule): a bare toLocale* reads the viewer's zone and moves a day. */
const FORMAT = new Intl.DateTimeFormat('en-GB', { timeZone: 'UTC', day: 'numeric', month: 'short', year: 'numeric' });
const fmtDate = (iso) => (iso ? FORMAT.format(new Date(iso)) : '');

/* One short phrase per entry. Never a count, never a verdict. */
const headline = (e) => {
  switch (e.kind) {
    case 'lesson': return e.title;
    case 'session': return e.session.title;
    case 'assignment': return e.title;
    case 'submission': return W.headline.submission;
    case 'note': return W.headline.note;
    case 'message': return e.subject;
    case 'signal': return W.headline.signal;
    /* The review's point by name. The product appends "review" to its own
       staff labels; this table's labels already say it ("Mid-programme
       review"), so appending would read "review review". */
    case 'evaluation': return (TL.evaluationKind || {})[e.evaluationKind] || e.evaluationKind;
    default: throw new Error('People/Head: no headline for kind "' + String(e.kind) + '"');
  }
};
const line = (e) => ((TL.kind || {})[e.kind] || e.kind) + ' · ' + headline(e);

/* WHERE THEY ARE. L89's own count, carried verbatim: steps done out of steps on
   the path, presented as a count. Never a percentage, never a bar, and a person
   with no path is told so in words rather than "0 of 0". */
const whereCount = person.stepsTotal === 0
  ? W.head.noPath
  : fill(W.head.steps, { done: person.stepsComplete, total: person.stepsTotal });
const where = person.lastActivity ? whereCount + ' · ' + fill(W.head.lastSeen, { when: fmtDate(person.lastActivity) }) : whereCount;

/* WHAT THEY JUST DID. The model bands `done` first, ascending, so the most
   recent finished thing is the LAST of them (L116's orderEntries). Quiet, never
   an accusation, when there is none: a learner who has just signed up is the
   person L89 built the roster to surface. */
const done = entries.filter((e) => e.state === 'done');
const justDid = done[done.length - 1];

/* WHAT IS NEXT: a DATED in-play entry preferred, falling back to the first. That
   is not the same as "the first one", and it is the kind of rule that silently
   degrades if it is re-derived — an undated lesson would otherwise outrank the
   session booked for Thursday. */
const inPlay = entries.filter((e) => e.state !== 'done');
const next = inPlay.find((e) => e.at !== null) || inPlay[0];

Outputs.facts = [
  { id: 'where', label: W.head.where, value: where },
  { id: 'justDid', label: W.head.justDid, value: justDid ? line(justDid) : W.head.nothingYet },
  { id: 'next', label: W.head.next, value: next ? line(next) + (next.at ? ' · ' + fmtDate(next.at) : '') : W.head.nothingScheduled }
];
